// Generated by php2rust. In release builds set overflow-checks = true, see the README.

fn php_ucwords(text: &str) -> String {
    let mut bytes = text.as_bytes().to_vec();
    let mut start = true;
    for byte in &mut bytes {
        if start {
            byte.make_ascii_uppercase();
        }
        start = matches!(*byte, b' ' | b'\t' | b'\r' | b'\n' | b'\x0C' | b'\x0B');
    }
    String::from_utf8(bytes).expect("only ASCII letters changed")
}

fn main() {
    let texts = vec![
        String::from("hello world"),
        String::from("hello  world"),
        String::from("a\tb\nc\rd\u{c}e\u{b}f"),
        String::from("élan vital"),
        String::from("x-y_z"),
        String::from("123abc def"),
        String::from(" lead"),
        String::from("trail "),
        String::from(""),
        String::from("\0a b"),
        String::from("ALREADY UP"),
        String::from("mIxEd cAsE"),
    ];
    for text in texts {
        print!("[");
        print!("{}", php_ucwords(&text));
        print!("]\n");
    }
}
